const fs = require('fs')
const os = require('os')
const path = require('path')
const crypto = require('crypto')
const { fileURLToPath, pathToFileURL } = require('url')

module.exports = wallpaper_sync

const uri_keys = {
  '/wallpaper/picture-uri': '/org/gnome/desktop/background/picture-uri',
  '/wallpaper/picture-uri-dark': '/org/gnome/desktop/background/picture-uri-dark'
}

// the wallpaper images (light and dark) as synced keys: /wallpaper/picture-uri -> "'<sha256>.<ext>'".
// downloaded images go to ~/.local/share/backgrounds/gnome-hypersync, nothing else is overwritten
function wallpaper_sync ({ dconf, files, index_file, env = process.env }) {
  const data_dir = env.XDG_DATA_HOME || path.join(os.homedir(), '.local', 'share')
  const save_dir = path.join(data_dir, 'backgrounds', 'gnome-hypersync')
  const api = { owns: key => key.startsWith('/wallpaper/'), read_all, write, prepare }
  return api

  // also remembers which local file has which hash, so a rollback can point back to the old file
  async function read_all () {
    const all = {}
    const index = await read_json(index_file) || {}
    for (const key in uri_keys) {
      const file = uri_to_path(await dconf.read(uri_keys[key]))
      const name = file && await name_file(file)
      if (!name) continue
      index[name] = file
      all[key] = `'${name}'`
    }
    await fs.promises.writeFile(index_file, JSON.stringify(index, null, 2))
    return all
  }

  async function prepare (key, value) {
    if (value === null) return
    const name = read_name(value)
    const index = await read_json(index_file) || {}
    await files.publish(name, await fs.promises.readFile(index[name]))
  }

  // null (no wallpaper file on the other device) changes nothing here
  async function write (key, value) {
    if (value === null) return
    const name = read_name(value)
    const known = (await read_json(index_file) || {})[name]
    const file = known && await name_file(known) === name ? known : await download({ name, files, save_dir })
    await dconf.write(uri_keys[key], `'${pathToFileURL(file).href.replace(/'/g, '%27')}'`)
  }
}

/***************************************
HELPERS
***************************************/
async function download ({ name, files, save_dir }) {
  const file = path.join(save_dir, name)
  await fs.promises.mkdir(save_dir, { recursive: true })
  await fs.promises.writeFile(file, await files.fetch(name))
  return file
}

// "'<sha256>.<ext>'" -> '<sha256>.<ext>', it becomes a file name so it is checked
function read_name (value) {
  const name = value.slice(1, -1)
  if (!/^[0-9a-f]{64}(\.[a-z0-9]{1,5})?$/i.test(name)) throw new Error('not a valid wallpaper name: ' + name)
  return name
}

// the content hash + the extension, null if the file is gone
async function name_file (file) {
  const data = await fs.promises.readFile(file).catch(() => null)
  if (!data) return null
  return crypto.createHash('sha256').update(data).digest('hex') + path.extname(file).toLowerCase()
}

function uri_to_path (value) {
  const uri = value?.slice(1, -1)
  return uri?.startsWith('file://') ? fileURLToPath(uri) : null
}

function read_json (file) { return fs.promises.readFile(file, 'utf8').then(JSON.parse).catch(() => null) }
